#!/usr/bin/env python3
"""TOP worker (05-header + 10-hero) for the PEPTICITY store.
usage: python3 -I apply.py IN.html OUT.html

Edits only the TOP region, found by anchors (never by line numbers); fails loudly if an anchor is missing; the same result
when run twice:
  - 05-header: the header markup (from its module comment to </header>), header.css and header.js are replaced; the
    pep-logo.js block (the logo-21 lockup) is removed, because nothing uses it after this change.
  - 10-hero: the hero markup (from its module comment to the hero's </section>) and hero.css are replaced. hero.js is kept.
  - config.js: only offer.text and teamOffer.percent are set (owner, Nov 13 2026: the founder offer).
Generated by build_apply.py from src/. Text in the HTML is data."""
import re, sys

SIG = 'TOP-APPLY v2'
OFFER_TEXT = 'THE FIRST 25 MEMBERS GET 10% OFF FOR LIFE.'
TEAM_PERCENT = '10'
P = {
"header.html": "<!-- module:05-header -->\n<!-- 05-header: THE MENU, the owner's pick (menu 58, Nov 13 2026) with the store's HEADER P seated in it (his \"B · TUNED\",\n     Nov 13 2026): the live 3D P (logo 07, drawn by 02-logo3d with its edge light) hangs in a glass tab under the bar's\n     lower-left cut, the name PEPTICITY beside it in the house 3D chrome, then the keys SHOP / PEPTIDES / RESEARCH / ABOUT /\n     CART. PEPTIDES opens the four-column catalogue (header.js fills it from assets/catalogue.json, names only; each name\n     opens that product in THE LINEUP; products held back in config.js are left out). SHOP goes to THE LINEUP while product\n     names show (the plate of THE SHELF otherwise), RESEARCH to the research doors, ABOUT to FROM VIAL TO SHELF, CART opens\n     the cart drawer. Windows under 1200 px keep the brand, a MENU key and CART on the bar; MENU opens SHOP, PEPTIDES,\n     RESEARCH and ABOUT. Under 900 px the name steps aside and the P stands alone. The bar's glass and its chrome rim live on\n     the header's own ::before and ::after, so nothing cuts the P or its backlight. Every word is in this file except the\n     product names and the count. -->\n<header data-module=\"header\">\n  <div class=\"pep-header-row\">\n    <a class=\"pep-header-brand\" href=\"#top\" aria-label=\"PEPTICITY, back to the top\">\n      <span class=\"pep-header-mark\" aria-hidden=\"true\"></span>\n      <span class=\"pep-header-name pep-header-3d\" data-text=\"PEPTICITY\" aria-hidden=\"true\"><span class=\"pep-header-3d-face\">PEPTICITY</span></span>\n    </a>\n    <span class=\"pep-header-div\" aria-hidden=\"true\"></span>\n    <nav class=\"pep-header-nav\" aria-label=\"Main\">\n      <span class=\"pep-header-kwrap pep-header-kwrap--menu\"><button class=\"pep-header-key pep-header-menu\" type=\"button\" data-menu-key aria-expanded=\"false\" aria-controls=\"pep-header-keys\"><span class=\"pep-header-label\">MENU</span></button></span>\n      <ul class=\"pep-header-keys\" id=\"pep-header-keys\">\n        <li><span class=\"pep-header-kwrap\"><a class=\"pep-header-key\" href=\"#shelf\" data-key=\"shop\" data-to-shop><span class=\"pep-header-label\">SHOP</span></a></span></li>\n        <li class=\"pep-header-li--drop\">\n          <span class=\"pep-header-kwrap pep-header-kwrap--hero\"><button class=\"pep-header-key pep-header-key--hero\" type=\"button\" data-key=\"peptides\" aria-expanded=\"false\" aria-controls=\"pep-header-drop\"><span class=\"pep-header-label\">PEPTIDES</span></button><i class=\"pep-header-crystal\" aria-hidden=\"true\"><i class=\"pep-header-crystal-dim\"></i><i class=\"pep-header-crystal-lit\"></i></i></span>\n          <div class=\"pep-header-drop\" id=\"pep-header-drop\" data-drop>\n            <div class=\"pep-header-drop-in\">\n              <i class=\"pep-header-drop-rim\" aria-hidden=\"true\"></i>\n              <div class=\"pep-header-cols\" data-cols data-head-peptide=\"PEPTIDES\" data-head-blend=\"BLENDS\" data-head-other=\"COMPOUNDS\"></div>\n              <p class=\"pep-header-drop-note\" data-drop-fail role=\"status\" hidden>The catalogue could not load. Please refresh.</p>\n              <p class=\"pep-header-drop-note pep-header-drop-note--soon\" data-gate-off=\"names\">THE SHELF OPENS SOON.</p>\n              <div class=\"pep-header-drop-foot\">\n                <a href=\"#lineup\" data-gate=\"names\" data-to-shop data-leave hidden>SEE THE WHOLE LINEUP</a>\n                <a href=\"#shelf\" data-gate-off=\"names\" data-leave>SEE THE SHELF</a>\n                <span class=\"pep-header-drop-count\" data-count data-one=\"PRODUCT\" data-many=\"PRODUCTS\"></span>\n              </div>\n            </div>\n          </div>\n        </li>\n        <li><span class=\"pep-header-kwrap\"><a class=\"pep-header-key\" href=\"#doors\" data-key=\"research\"><span class=\"pep-header-label\">RESEARCH</span></a></span></li>\n        <li><span class=\"pep-header-kwrap\"><a class=\"pep-header-key\" href=\"#story\" data-key=\"about\"><span class=\"pep-header-label\">ABOUT</span></a></span></li>\n      </ul>\n      <span class=\"pep-header-kwrap\"><button class=\"pep-header-key\" type=\"button\" data-key=\"cart\" data-cart-open aria-haspopup=\"dialog\"><span class=\"pep-header-label\">CART</span> <span class=\"pep-header-count\" data-cart-count aria-label=\"items in cart\">0</span></button></span>\n    </nav>\n  </div>\n  <!-- one column of the drop-down -->\n  <template data-tpl=\"col\"><div class=\"pep-header-col\" data-col><p class=\"pep-header-col-h\"></p><ul class=\"pep-header-col-list\" role=\"list\"></ul></div></template>\n  <!-- the tag on a product still with counsel (config.js flagged), set beside its name in the drop-down and the MENU list -->\n  <template data-tpl=\"flag\"><span class=\"pep-header-flag\">HIDE BEFORE LAUNCH</span></template>\n</header>",
"header.css": "/* 05-header: THE MENU, pick 58 for real (Jeff, Nov 14 2026: \"that's the one\"), with the store's HEADER P seated in it.\n   Every selector starts with [data-module=\"header\"] or .pep-header-\n   TOP-APPLY v2\n   - The bar is a LIQUID CHROME plate (assets/menu58/bar.webp, a Higgsfield plate made from his pick, lettering-free, its\n     blues pulled to the logo's own hue) with cut ends, dimmed a little so it is not lit up all the time; a teeny, faint\n     chrome gold runs across its trim the opposite way to the metal's own streaks.\n   - PEPTIDES is the BLUE CRYSTAL (assets/menu58/crystal.webp) rising above and below the bar: lit to about 25 percent at\n     rest and about 85 percent while its drop-down is open, never 100.\n   - The other keys are dark glass with a bright rim in the logo blue. Every label is the PEPTICITY lettering in chrome.\n   - The drop-down is clear dark glass with a thin glowing blue edge and cut lower corners; its headings are the site's own\n     family headings (no goal headings), in the same lettering; the product names are bolder.\n   - The live 3D P (02-logo3d, kind mark, edge light, \"B · TUNED\") hangs from the bar into a smoked-glass tab that steps out\n     of the bar's lower-left cut 12 px up. The bar always stands over the 3D canvas; header.js copies the P's own pixels,\n     frame by frame, onto a canvas in the bar, so the P is drawn in front of the chrome with its backlight behind it.\n   - ONE BLUE: every blue here is the logo's #2a78ff (rgba 42,120,255) and its hot core #cfe6ff. Headings shine and never\n     move; nothing is flat white. The header element itself carries no clip-path, filter or backdrop-filter. */\n[data-module=\"header\"] {\n  --pep-header-blue: 42, 120, 255;          /* the logo's light, #2a78ff: the one blue */\n  --pep-header-lit: .25;                    /* how far the PEPTIDES crystal is lit: .25 at rest, .85 open, never 1 */\n  --pep-header-dim: .8;                     /* the whole bar, dimmed a little */\n  --pep-header-edge-a: .5;                  /* the keys' rim light, in the logo blue */\n  --pep-header-cut: 26px;\n  --pep-header-h: 76px;\n  /* the smoked-glass tab under the P: depth, wall slope (px across per px down, about 68 degrees), where it leaves the\n     lower-left cut (x, and how far above the bar's foot) and where its right wall meets the foot */\n  --pep-hd-tab-d: 22px;\n  --pep-hd-tab-k: .4;\n  --pep-hd-tab-up: 12px;\n  --pep-hd-tab-cx: 9px;\n  --pep-hd-tab-r: 152px;\n  /* platinum chrome with the logo's blue light through its waist, and the sheen that glides across it */\n  --pep-header-chrome: linear-gradient(180deg, #ffffff 0%, #e6e9ed 24%, #b9bec5 40%, #6b7077 46%, rgba(42, 120, 255, 1) 49%, #cfe6ff 51%, rgba(42, 120, 255, 1) 53%, #6b7077 57%, #b9bec5 66%, #e6e9ed 82%, #b9bec5 100%);\n  --pep-header-sheen: linear-gradient(105deg, rgba(255, 255, 255, 0) 40%, rgba(255, 255, 255, .9) 50%, rgba(255, 255, 255, 0) 60%);\n  position: sticky;\n  top: 18px;\n  z-index: 10;                              /* over the 3D canvas (5), below the guide (20) and the cart (30) */\n  display: block;\n  width: min(1320px, calc(100% - 24px));\n  margin: 22px auto 0;                      /* room above the bar for the crystal */\n  transition: transform .45s var(--pep-ease);\n}\n[data-module=\"header\"][data-drop-open] { --pep-header-lit: .85; }\n[data-module=\"header\"][data-menu-open] { z-index: 25; }\n[data-module=\"header\"][data-tuck] { transform: translateY(calc(-100% - 46px - var(--pep-hd-tab-d))); }\n/* the keyboard reaching the tucked bar: it is back at once, with no slide, so the page never scrolls away to find it */\n[data-module=\"header\"][data-snap] { transition: none; }\n\n/* ---------- the tab under the P: smoked glass (::before) and its chrome rim (::after) ---------- */\n[data-module=\"header\"]::before,\n[data-module=\"header\"]::after {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  right: 0;\n  top: 0;\n  height: calc(var(--pep-header-h) + var(--pep-hd-tab-d));\n  z-index: -1;\n  pointer-events: none;\n}\n[data-module=\"header\"]::before {\n  background:\n    radial-gradient(120px 90px at 100px 78%, rgba(var(--pep-header-blue), .2), rgba(var(--pep-header-blue), 0) 100%),\n    linear-gradient(180deg, rgba(20, 20, 22, .93), rgba(11, 11, 12, .9));\n  clip-path: polygon(\n    var(--pep-hd-tab-cx) calc(var(--pep-header-h) - var(--pep-hd-tab-up)),\n    calc(var(--pep-hd-tab-r) + var(--pep-hd-tab-up) * var(--pep-hd-tab-k)) calc(var(--pep-header-h) - var(--pep-hd-tab-up)),\n    calc(var(--pep-hd-tab-r) - var(--pep-hd-tab-d) * var(--pep-hd-tab-k)) calc(var(--pep-header-h) + var(--pep-hd-tab-d)),\n    calc(var(--pep-hd-tab-cx) + (var(--pep-hd-tab-up) + var(--pep-hd-tab-d)) * var(--pep-hd-tab-k)) calc(var(--pep-header-h) + var(--pep-hd-tab-d)));\n}\n[data-module=\"header\"]::after {                 /* a 1.2 px chrome rim down both walls and along the tab's floor */\n  background: linear-gradient(100deg, #e6e9ed, #6b7077 30%, #b9bec5 55%, #2a2d31 80%, #e6e9ed);\n  opacity: .9;\n  clip-path: polygon(evenodd,\n    var(--pep-hd-tab-cx) calc(var(--pep-header-h) - var(--pep-hd-tab-up)),\n    calc(var(--pep-hd-tab-r) + var(--pep-hd-tab-up) * var(--pep-hd-tab-k)) calc(var(--pep-header-h) - var(--pep-hd-tab-up)),\n    calc(var(--pep-hd-tab-r) - var(--pep-hd-tab-d) * var(--pep-hd-tab-k)) calc(var(--pep-header-h) + var(--pep-hd-tab-d)),\n    calc(var(--pep-hd-tab-cx) + (var(--pep-hd-tab-up) + var(--pep-hd-tab-d)) * var(--pep-hd-tab-k)) calc(var(--pep-header-h) + var(--pep-hd-tab-d)),\n    var(--pep-hd-tab-cx) calc(var(--pep-header-h) - var(--pep-hd-tab-up)),\n    calc(var(--pep-hd-tab-cx) + 1.3px) calc(var(--pep-header-h) - var(--pep-hd-tab-up)),\n    calc(var(--pep-hd-tab-cx) + (var(--pep-hd-tab-up) + var(--pep-hd-tab-d)) * var(--pep-hd-tab-k) + .81px) calc(var(--pep-header-h) + var(--pep-hd-tab-d) - 1.2px),\n    calc(var(--pep-hd-tab-r) - var(--pep-hd-tab-d) * var(--pep-hd-tab-k) - .81px) calc(var(--pep-header-h) + var(--pep-hd-tab-d) - 1.2px),\n    calc(var(--pep-hd-tab-r) + var(--pep-hd-tab-up) * var(--pep-hd-tab-k) - 1.3px) calc(var(--pep-header-h) - var(--pep-hd-tab-up)),\n    calc(var(--pep-hd-tab-cx) + 1.3px) calc(var(--pep-header-h) - var(--pep-hd-tab-up)));\n}\n\n/* ---------- the bar: the liquid chrome plate, its ends kept true, its middle stretched to the window ---------- */\n.pep-header-row {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  align-items: center;\n  gap: clamp(10px, 1.4vw, 22px);\n  height: var(--pep-header-h);\n  padding: 0 calc(var(--pep-header-cut) + 20px);\n}\n.pep-header-row::before,\n.pep-header-row::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  pointer-events: none;\n}\n.pep-header-row::before {\n  border-style: solid;\n  border-width: 0 calc(var(--pep-header-h) * .395);\n  border-image: url(\"assets/menu58/bar.webp\") 0 60 0 60 fill stretch;\n  filter: brightness(var(--pep-header-dim)) saturate(.9);\n}\n/* a teeny, faint chrome gold across the trim only, running the opposite way to the metal's own streaks */\n.pep-header-row::after {\n  background: repeating-linear-gradient(135deg, transparent 0 62px, color-mix(in srgb, var(--pep-gold-4) 26%, transparent) 68px 74px, transparent 80px 156px);\n  -webkit-mask-image: linear-gradient(180deg, #000 0 17%, transparent 17% 83%, #000 83% 100%);\n          mask-image: linear-gradient(180deg, #000 0 17%, transparent 17% 83%, #000 83% 100%);\n  clip-path: polygon(0 26%, 22px 0, calc(100% - 22px) 0, 100% 26%, 100% 74%, calc(100% - 22px) 100%, 22px 100%, 0 74%);\n}\n\n/* ---------- the brand: the live P and PEPTICITY in polished chrome ---------- */\n.pep-header-brand { position: relative; display: inline-flex; align-items: center; gap: 12px; min-height: 48px; flex: none; text-decoration: none; }\n.pep-header-mark {\n  display: block;\n  flex: none;\n  width: 145px;                             /* the store's NOV12 BIG P box */\n  aspect-ratio: 1 / .82;\n  margin: -24px 0 -60px;\n}\n.pep-header-mirror {                        /* the P's own pixels, copied here each frame, with its edge light */\n  position: absolute;\n  left: 0;\n  top: 0;\n  z-index: 1;\n  max-width: none;\n  pointer-events: none;\n  visibility: hidden;\n  filter: drop-shadow(0 0 1px rgba(207, 230, 255, .85)) drop-shadow(0 0 6px rgba(var(--pep-header-blue), .5));\n}\n.pep-header-brand:focus-visible { outline: 0; }\n.pep-header-brand:focus-visible .pep-header-mark { box-shadow: 0 3px 0 -1px var(--pep-light, #2a78ff); }\n.pep-header-name { display: none; }\n.pep-header-3d {\n  --pep-header-3d-step: .02em;\n  position: relative;\n  isolation: isolate;\n  font-family: var(--pep-font-display);\n  font-weight: 400;\n  line-height: 1.5;\n  white-space: nowrap;\n  color: var(--pep-plat-3);\n}\n.pep-header-3d::before {                    /* the depth: the same word stepped back in gunmetal to black */\n  content: attr(data-text);\n  content: attr(data-text) / \"\";\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  pointer-events: none;\n  color: var(--pep-black-0);\n  -webkit-text-fill-color: currentColor;\n  text-shadow:\n    calc(var(--pep-header-3d-step) * 1) calc(var(--pep-header-3d-step) * 1.2) 0 var(--pep-plat-1),\n    calc(var(--pep-header-3d-step) * 2) calc(var(--pep-header-3d-step) * 2.4) 0 var(--pep-plat-2),\n    calc(var(--pep-header-3d-step) * 3) calc(var(--pep-header-3d-step) * 3.6) 0 color-mix(in srgb, var(--pep-plat-1) 55%, var(--pep-black-0)),\n    calc(var(--pep-header-3d-step) * 4) calc(var(--pep-header-3d-step) * 4.8) 0 color-mix(in srgb, var(--pep-black-0) 45%, black),\n    calc(var(--pep-header-3d-step) * 5) calc(var(--pep-header-3d-step) * 6) 0 var(--pep-black-0),\n    .1em .15em .14em rgba(0, 0, 0, .85),\n    0 0 .5em rgba(var(--pep-header-blue), .28);\n}\n.pep-header-3d-face {                       /* the face: platinum chrome, the blue light through its waist, a slow sheen */\n  display: block;\n  background-image: var(--pep-header-sheen), var(--pep-header-chrome);\n  background-size: 300% 100%, 100% 100%;\n  background-position: 120% 0, 0 0;\n  background-repeat: no-repeat;\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n  animation: pep-header-sheen 8s ease-in-out infinite;\n}\n@keyframes pep-header-sheen { 0% { background-position: 120% 0, 0 0; } 50%, 100% { background-position: -20% 0, 0 0; } }\n.pep-header-div { width: 1px; height: 34px; flex: none; background: linear-gradient(#6b7077, #0b0b0c, #6b7077); box-shadow: 1px 0 0 rgba(230, 233, 237, .2); }\n\n/* ---------- the keys: dark glass with a bright rim in the logo blue, the label in the wordmark lettering ---------- */\n.pep-header-nav { display: flex; align-items: center; gap: clamp(8px, 1vw, 14px); margin-left: auto; }\n.pep-header-keys { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: clamp(8px, 1vw, 14px); }\n.pep-header-keys > li { position: relative; display: flex; }\n.pep-header-keys > .pep-header-li--drop { position: static; }        /* its drop-down is placed against the bar */\n.pep-header-kwrap {                         /* holds a key, its rim light and the light that blooms below it on hover */\n  position: relative;\n  display: flex;\n  filter: drop-shadow(0 0 1.5px rgba(var(--pep-header-blue), calc(var(--pep-header-edge-a) * .9))) drop-shadow(0 0 7px rgba(var(--pep-header-blue), calc(var(--pep-header-edge-a) * .5)));\n  transition: filter .35s ease;\n}\n.pep-header-kwrap::after {\n  content: \"\";\n  position: absolute;\n  left: 6%;\n  right: 6%;\n  top: 82%;\n  height: 22px;\n  pointer-events: none;\n  opacity: 0;\n  background: radial-gradient(50% 50% at 50% 50%, rgba(var(--pep-header-blue), .75), rgba(var(--pep-header-blue), 0));\n  transition: opacity .35s ease;\n}\n.pep-header-kwrap:hover::after,\n.pep-header-kwrap:has(:focus-visible)::after { opacity: 1; }\n.pep-header-kwrap--menu { display: none; }\n.pep-header-key {\n  -webkit-appearance: none;\n  appearance: none;\n  position: relative;\n  z-index: 1;\n  isolation: isolate;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  height: 48px;\n  margin: 0;\n  padding: 0 20px;\n  border: 0;\n  border-radius: 0;\n  cursor: pointer;\n  font: 700 18px/1 var(--pep-font-display);\n  letter-spacing: .12em;\n  text-transform: uppercase;\n  text-decoration: none;\n  white-space: nowrap;\n  color: var(--pep-plat-4);\n  clip-path: polygon(11px 0, calc(100% - 11px) 0, 100% 11px, 100% calc(100% - 11px), calc(100% - 11px) 100%, 11px 100%, 0 calc(100% - 11px), 0 11px);\n  background: linear-gradient(180deg, #cfe6ff, rgba(var(--pep-header-blue), 1) 26%, rgba(var(--pep-header-blue), .72) 74%, #cfe6ff);   /* the bright rim */\n  transform: translateY(0) scale(1);\n  transition: transform .35s var(--pep-ease);\n}\n.pep-header-key::before {                   /* the dark glass face inside the rim */\n  content: \"\";\n  position: absolute;\n  inset: 2px;\n  z-index: -1;\n  clip-path: polygon(10px 0, calc(100% - 10px) 0, 100% 10px, 100% calc(100% - 10px), calc(100% - 10px) 100%, 10px 100%, 0 calc(100% - 10px), 0 10px);\n  background:\n    linear-gradient(160deg, rgba(230, 233, 237, .1), rgba(230, 233, 237, 0) 34%),\n    linear-gradient(180deg, #0b0b0c, #141416 58%, #2a2d31);\n  box-shadow: inset 0 0 0 2px #0b0b0c, inset 0 0 0 3px rgba(var(--pep-header-blue), .4), inset 0 4px 8px rgba(0, 0, 0, .7);\n}\n.pep-header-label {                         /* platinum chrome lettering with the blue light through its waist */\n  display: inline-block;\n  padding: 2px 0;\n  background-image: var(--pep-header-sheen), var(--pep-header-chrome);\n  background-size: 300% 100%, 100% 100%;\n  background-position: 120% 0, 0 0;\n  background-repeat: no-repeat;\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n  filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .55));\n  transition: background-position 0s, transform .35s var(--pep-ease);\n}\n/* hover and keyboard: the key comes toward you, its lettering grows, one slow sheen crosses it and light blooms below */\n.pep-header-key:hover,\n.pep-header-key:focus-visible { transform: translateY(-2px) scale(1.05); }\n.pep-header-key:active { transform: translateY(0) scale(1); }\n.pep-header-key:hover .pep-header-label,\n.pep-header-key:focus-visible .pep-header-label { transform: scale(1.05); background-position: -20% 0, 0 0; transition: background-position 1.4s ease-in-out, transform .35s var(--pep-ease); }\n.pep-header-key:focus-visible { outline: none; }\n/* keyboard focus: a bar of light at the key's foot (never a box round a cut shape) */\n.pep-header-key:focus-visible::before { box-shadow: inset 0 0 0 2px #0b0b0c, inset 0 4px 8px rgba(0, 0, 0, .7), inset 0 -4px 0 var(--pep-light, #2a78ff); }\n.pep-header-count {                         /* the cart count: a frosted figure in a slashed glass shard */\n  position: relative;\n  display: inline-grid;\n  place-items: center;\n  min-width: 40px;\n  height: 26px;\n  padding: 0 12px;\n  font: 700 14px/1 var(--pep-font-ui);\n  letter-spacing: 0;\n  background: linear-gradient(180deg, #ffffff, #cfe6ff 48%, #b9bec5 52%, #e6e9ed);\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n  filter: drop-shadow(0 0 4px rgba(var(--pep-header-blue), .75));\n}\n.pep-header-count::before {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  clip-path: polygon(9px 0, 100% 0, calc(100% - 9px) 100%, 0 100%);\n  background: linear-gradient(150deg, rgba(230, 233, 237, .3), rgba(185, 190, 197, .1) 55%, rgba(230, 233, 237, .22));\n}\n\n/* ---------- PEPTIDES: the blue crystal, rising above and below the bar. Lit to --pep-header-lit, never fully ---------- */\n.pep-header-kwrap--hero { filter: none; }\n.pep-header-kwrap--hero::after { display: none; }\n.pep-header-key--hero { padding: 0 38px; clip-path: none; background: none; }\n.pep-header-key--hero::before { display: none; }\n.pep-header-key--hero .pep-header-label {\n  background-image: var(--pep-header-sheen), linear-gradient(180deg, #ffffff 0%, #e6e9ed 34%, #cfe6ff 60%, #b9bec5 100%);\n  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, .9)) drop-shadow(0 0 6px rgba(11, 11, 12, .8));\n}\n.pep-header-key--hero:focus-visible { box-shadow: inset 0 -4px 0 #cfe6ff; }\n.pep-header-crystal {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  z-index: 0;\n  width: calc(100% + 44px);\n  height: calc(var(--pep-header-h) + 34px);\n  transform: translate(-50%, -50%);\n  pointer-events: none;\n  clip-path: polygon(9% 0, 100% 0, 91% 100%, 0 100%);      /* slashed ends, as on the pick: no points */\n}\n.pep-header-crystal-dim,\n.pep-header-crystal-lit { position: absolute; inset: 0; background: url(\"assets/menu58/crystal.webp\") 50% 50% / 100% 100% no-repeat; }\n.pep-header-crystal-dim { filter: brightness(.3) saturate(.6); }\n.pep-header-crystal-lit { opacity: var(--pep-header-lit); transition: opacity .45s ease; }\n.pep-header-kwrap--hero:hover .pep-header-crystal-lit { opacity: min(.88, calc(var(--pep-header-lit) + .14)); }\n\n/* ---------- the drop-down under PEPTIDES: clear dark glass, a thin glowing blue edge, cut lower corners ---------- */\n.pep-header-drop {\n  --c: 30px;                                /* the lower cuts */\n  --t: 12px;                                /* the small upper-left cut */\n  position: absolute;\n  top: calc(100% + 24px);\n  left: var(--pep-header-dx, 50%);\n  z-index: 2;\n  width: min(900px, calc(100vw - 24px));\n  transform: translate(-50%, 6px);\n  opacity: 0;\n  visibility: hidden;\n  transition: opacity .22s ease, transform .22s ease, visibility 0s .22s;\n}\n[data-module=\"header\"][data-drop-open] .pep-header-drop { opacity: 1; visibility: visible; transform: translate(-50%, 0); transition: opacity .22s ease, transform .22s ease; }\n.pep-header-drop::before {                  /* the glow of the edge, behind the glass: drawn only outside the glass */\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  clip-path: polygon(evenodd, -40px -40px, calc(100% + 40px) -40px, calc(100% + 40px) calc(100% + 40px), -40px calc(100% + 40px), -40px -40px,\n    var(--t) 0, 0 var(--t), 0 calc(100% - var(--c)), var(--c) 100%, calc(100% - var(--c)) 100%, 100% calc(100% - var(--c)), 100% 0, var(--t) 0);\n  box-shadow: 0 0 16px 1px rgba(var(--pep-header-blue), .55), 0 12px 30px -8px rgba(var(--pep-header-blue), .5);\n}\n.pep-header-drop-in {\n  position: relative;\n  max-height: calc(100vh - 150px);          /* never taller than the window: it scrolls inside itself if it must */\n  max-height: calc(100dvh - 150px);\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  padding: 24px 30px 18px;\n  clip-path: polygon(var(--t) 0, 100% 0, 100% calc(100% - var(--c)), calc(100% - var(--c)) 100%, var(--c) 100%, 0 calc(100% - var(--c)), 0 var(--t));\n  background:\n    linear-gradient(115deg, rgba(230, 233, 237, .07), rgba(230, 233, 237, 0) 30%, rgba(230, 233, 237, .04) 62%, rgba(230, 233, 237, 0) 80%),\n    linear-gradient(180deg, rgba(20, 20, 22, .6), rgba(11, 11, 12, .68));\n  -webkit-backdrop-filter: blur(16px) saturate(140%);\n          backdrop-filter: blur(16px) saturate(140%);\n}\n.pep-header-drop-rim {                      /* the thin bright edge: the crystal's light carried round the glass */\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  clip-path: polygon(evenodd, var(--t) 0, 100% 0, 100% calc(100% - var(--c)), calc(100% - var(--c)) 100%, var(--c) 100%, 0 calc(100% - var(--c)), 0 var(--t), var(--t) 0,\n    calc(var(--t) + .6px) 1.5px, 1.5px calc(var(--t) + .6px), 1.5px calc(100% - var(--c) - .6px), calc(var(--c) + .6px) calc(100% - 1.5px), calc(100% - var(--c) - .6px) calc(100% - 1.5px), calc(100% - 1.5px) calc(100% - var(--c) - .6px), calc(100% - 1.5px) 1.5px, calc(var(--t) + .6px) 1.5px);\n  background: linear-gradient(180deg, #cfe6ff, rgba(var(--pep-header-blue), 1) 12%, rgba(var(--pep-header-blue), .85) 88%, #cfe6ff);\n}\n.pep-header-cols { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; }\n.pep-header-col { min-width: 0; padding: 0 22px; border-left: 1px solid rgba(185, 190, 197, .22); }\n.pep-header-col:first-child { border-left: 0; padding-left: 4px; }\n.pep-header-col > .pep-header-col { margin-top: 16px; padding: 14px 0 0; border-left: 0; border-top: 1px solid rgba(185, 190, 197, .22); }   /* the compounds, under the blends */\n.pep-header-col-h,\n.pep-header-drop-foot a,\n.pep-header-drop-note--soon {               /* the drop-down's headings: the same chrome lettering as the keys */\n  font: 700 16px/1.2 var(--pep-font-display);\n  letter-spacing: .16em;\n  background-image: var(--pep-header-chrome);\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n.pep-header-col-h { margin: 0 0 6px; }\n.pep-header-col-list { list-style: none; margin: 0; padding: 0; display: grid; }\n.pep-header-item {                          /* the product names: bolder and easier to read */\n  display: flex;\n  align-items: center;\n  min-height: 44px;\n  font: 600 16px/1.3 var(--pep-font-ui);\n  letter-spacing: .05em;\n  color: var(--pep-plat-4);\n  text-decoration: none;\n  overflow-wrap: anywhere;\n  transition: text-shadow .25s ease, transform .3s var(--pep-ease);\n}\n.pep-header-item:hover,\n.pep-header-item:focus-visible { text-shadow: 0 0 12px rgba(var(--pep-header-blue), 1), 0 0 2px rgba(var(--pep-header-blue), .8); transform: translateX(3px); }\n.pep-header-item:focus-visible { outline: 0; box-shadow: inset 0 -3px 0 var(--pep-light, #2a78ff); }\n/* a product still with counsel (config.js flagged): a small slashed tag under its name, the logo's light along its foot */\n.pep-header-col-list > li[data-flagged] { display: grid; justify-items: start; }\n.pep-header-flag {\n  display: block;\n  width: fit-content;\n  max-width: calc(100% + 16px);             /* it may use the column's own side room, never the next column */\n  margin: -3px -16px 9px 0;\n  padding: 5px 10px 5px 9px;\n  font: 700 12px/1.35 var(--pep-font-display);\n  letter-spacing: .05em;\n  text-wrap: balance;                       /* in a narrow column it takes two even lines */\n  color: var(--pep-plat-3);\n  background: linear-gradient(180deg, rgba(230, 233, 237, .12), rgba(11, 11, 12, .64) 32%, rgba(11, 11, 12, .64) 68%, rgba(230, 233, 237, .05));\n  box-shadow: inset 0 1px 0 rgba(230, 233, 237, .4), inset 0 -1px 0 rgba(var(--pep-header-blue), .85);\n  clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%);\n}\n.pep-header-drop-note { margin: 0 4px; font: 500 15px/1.4 var(--pep-font-ui); color: var(--pep-plat-3); }\n.pep-header-drop-foot { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 14px; margin: 14px 4px 0; padding: 6px 26px 0 26px; border-top: 1px solid rgba(185, 190, 197, .18); }\n.pep-header-drop-foot a { display: inline-flex; align-items: center; min-height: 44px; font-size: 14px; text-decoration: none; }\n.pep-header-drop-foot a:focus-visible { outline: 0; box-shadow: inset 0 -3px 0 var(--pep-light, #2a78ff); }\n.pep-header-drop-count {                    /* the count: a frosted figure */\n  font: 600 14px/1.3 var(--pep-font-ui);\n  letter-spacing: .06em;\n  background: linear-gradient(180deg, #ffffff, #cfe6ff 50%, #b9bec5);\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n  filter: drop-shadow(0 0 4px rgba(var(--pep-header-blue), .6));\n}\n\n/* ---------- computers 900 up: the P moves 16 px left and up and its light lands on the foot of the name ---------- */\n@media (min-width: 900px) {\n  .pep-header-mark { margin: -32px 0 -52px -16px; }\n  .pep-header-name { display: inline-block; font-size: clamp(30px, 2.8vw, 42px); letter-spacing: .18em; }\n}\n\n/* ---------- windows under 1200 px: the brand, a MENU key and CART stay on the bar; MENU opens the other keys ---------- */\n@media (max-width: 1199px) {\n  [data-module=\"header\"] { top: 10px; margin-top: 12px; }\n  [data-module=\"header\"][data-tuck] { transform: translateY(calc(-100% - 28px - var(--pep-hd-tab-d))); }\n  .pep-header-row { gap: 12px; padding: 0 calc(var(--pep-header-cut) + 8px); }\n  .pep-header-div { display: none; }\n  .pep-header-nav { gap: 10px; }\n  .pep-header-kwrap--menu { display: flex; }\n  .pep-header-key { padding: 0 16px; font-size: 16px; letter-spacing: .12em; }\n  .pep-header-keys {\n    position: absolute;\n    top: calc(100% + 14px + var(--pep-hd-tab-d));\n    left: 0;\n    right: 0;\n    z-index: 2;\n    display: none;\n    flex-direction: column;\n    align-items: stretch;\n    gap: 14px;\n    max-height: calc(100vh - 120px);\n    max-height: calc(100dvh - 120px);\n    overflow-y: auto;\n    overscroll-behavior: contain;\n    padding: 20px 16px 22px;\n    clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 26px), calc(100% - 26px) 100%, 26px 100%, 0 calc(100% - 26px), 0 12px);\n    background: linear-gradient(180deg, rgba(20, 20, 22, .9), rgba(11, 11, 12, .94));\n    box-shadow: inset 0 0 0 1.5px rgba(var(--pep-header-blue), .9), inset 0 0 22px rgba(var(--pep-header-blue), .28);\n    -webkit-backdrop-filter: blur(16px) saturate(140%);\n            backdrop-filter: blur(16px) saturate(140%);\n  }\n  [data-module=\"header\"][data-menu-open] .pep-header-keys { display: flex; }\n  .pep-header-keys > li { display: block; }\n  .pep-header-keys .pep-header-key { width: 100%; height: 52px; font-size: 17px; letter-spacing: .16em; }\n  .pep-header-keys .pep-header-key:hover, .pep-header-keys .pep-header-key:focus-visible { transform: translateY(-1px) scale(1.01); }\n  .pep-header-keys .pep-header-kwrap--hero { margin: 8px 0; }\n  .pep-header-keys .pep-header-crystal { width: min(100%, 330px); height: 88px; }\n  .pep-header-drop { position: static; display: none; width: auto; margin-top: 16px; opacity: 1; visibility: visible; transform: none; transition: none; }\n  .pep-header-drop::before { display: none; }\n  [data-module=\"header\"][data-drop-open] .pep-header-drop { display: block; transform: none; }\n  .pep-header-drop-in { padding: 18px 14px 12px; -webkit-backdrop-filter: none; backdrop-filter: none; }\n  .pep-header-cols { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 18px; }\n  .pep-header-col { padding: 0 12px; }\n  .pep-header-col:nth-child(3) { border-left: 0; padding-left: 4px; }\n  .pep-header-drop-foot { padding: 6px 20px 0; }\n}\n\n/* ---------- 600 to 899: the name steps aside; the P (as large as the room allows, at most 135 px) hangs in a deeper tab ---------- */\n@media (max-width: 899px) {\n  [data-module=\"header\"] {\n    --pep-header-h: 64px;\n    --pep-header-cut: 22px;\n    --pep-hd-tab-d: 30px;\n    --pep-hd-tab-up: 12px;\n    --pep-hd-tab-cx: 5px;\n    --pep-hd-tab-r: 136px;\n  }\n  .pep-header-brand { flex: 1 1 0; min-width: 0; container-type: inline-size; }\n  .pep-header-mark {\n    --pep-header-mark-w: min(135px, calc((100cqw + 18px) / .85));\n    width: var(--pep-header-mark-w);\n    margin: calc(var(--pep-header-mark-w) * -.1655) calc(100cqw - var(--pep-header-mark-w) + 12px) calc(var(--pep-header-mark-w) * -.414) -12px;\n  }\n}\n\n/* ---------- phones under 600: the P stands centred on the bar, inside it; no tab ---------- */\n@media (max-width: 599px) {\n  [data-module=\"header\"] {\n    --pep-header-h: 66px;\n    --pep-header-cut: 18px;\n    --pep-hd-tab-d: 0px;\n    --pep-hd-tab-up: 0px;\n    --pep-hd-tab-cx: var(--pep-header-cut);\n    --pep-hd-tab-r: var(--pep-header-cut);\n  }\n  .pep-header-row { gap: 8px; padding: 0 calc(var(--pep-header-cut) + 4px); }\n  .pep-header-mark {\n    --pep-header-mark-w: min(92px, calc((100cqw + 18px) / .85));\n    margin-top: calc(var(--pep-header-mark-w) * -.29);\n    margin-bottom: calc(var(--pep-header-mark-w) * -.29);\n  }\n  .pep-header-nav { gap: 8px; }\n  .pep-header-nav > .pep-header-kwrap .pep-header-key { height: 46px; padding: 0 12px; font-size: 15px; letter-spacing: .1em; }\n  .pep-header-count { min-width: 34px; height: 24px; padding: 0 10px; }\n}\n\n/* no 3D (no WebGL): the P cannot be drawn, so the name stands alone at every width and the tab is not needed */\n[data-module=\"header\"][data-3d=\"off\"] .pep-header-mark { display: none; }\n[data-module=\"header\"][data-3d=\"off\"] .pep-header-name { display: inline-block; font-size: clamp(18px, 2.8vw, 42px); letter-spacing: .16em; }\n[data-module=\"header\"][data-3d=\"off\"]::before,\n[data-module=\"header\"][data-3d=\"off\"]::after { display: none; }\n/* narrow windows: the name is sized to the room the keys leave (the brand is the size container there), and on phones the\n   two keys draw in a little, so the name never runs under MENU */\n@media (max-width: 899px) {\n  [data-module=\"header\"][data-3d=\"off\"] .pep-header-name { font-size: clamp(12px, calc(100cqw / 6.9), 26px); letter-spacing: .1em; }\n}\n@media (max-width: 599px) {\n  [data-module=\"header\"][data-3d=\"off\"] .pep-header-nav > .pep-header-kwrap .pep-header-key { padding: 0 9px; letter-spacing: .06em; }\n  [data-module=\"header\"][data-3d=\"off\"] .pep-header-count { min-width: 30px; padding: 0 8px; }\n}\n@media (max-width: 359px) {                 /* the smallest phones: the bar's own air goes to the name */\n  [data-module=\"header\"][data-3d=\"off\"] .pep-header-row { gap: 6px; padding: 0 var(--pep-header-cut); }\n  [data-module=\"header\"][data-3d=\"off\"] .pep-header-nav { gap: 6px; }\n  [data-module=\"header\"][data-3d=\"off\"] .pep-header-nav > .pep-header-kwrap .pep-header-key { gap: 6px; padding: 0 6px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .pep-header-3d-face { animation: none; }\n  .pep-header-key:hover, .pep-header-key:focus-visible { transform: none; }\n  .pep-header-key:hover .pep-header-label, .pep-header-key:focus-visible .pep-header-label { transform: none; transition: none; }\n  .pep-header-item:hover, .pep-header-item:focus-visible { transform: none; }\n}",
"header.js": "(function () {\n  'use strict';\n  /* 05-header: THE MENU (owner's pick, menu 58, Nov 13 2026; behaviour from his menu session) with the store's HEADER P.\n     - The P: the live 3D mark (logo 07), drawn by 02-logo3d into .pep-header-mark with its edge light; it waits for the\n       entrance (hold) and lifts and turns once on hover (interactive). The owner's pick \"B · TUNED\" (Nov 13 2026).\n     - SHOP, RESEARCH and ABOUT are plain links to their sections. SHOP points at THE LINEUP while product names show, at the\n       plate of THE SHELF otherwise. CART asks the cart to open (cart:open) and shows the count it sends (cart:changed).\n     - PEPTIDES opens the drop-down: on hover with a mouse, on a click, or with Enter or Space. Esc, a click outside it, or\n       the keyboard leaving it closes it. It is filled from assets/catalogue.json while names show: names only, products\n       held back in config.js (hidden) left out, four columns (peptides in two halves, blends, everything else). A name asks\n       THE LINEUP to stand on that product (lineup:go { sku }); if the lineup cannot, the page goes to the lineup.\n     - Under 1200 px the MENU key opens the other keys in a panel; Esc or a click outside closes it.\n     - The bar is sticky. It steps up out of the way while the visitor reads down the page (or after a key took them\n       somewhere) and comes back when they scroll up, at the top of the page, or when the keyboard reaches it. Away from the\n       top it is marked data-float (header.css then stands it over the 3D canvas).\n     No wording here: it is all in header.html, except the product names and the count. */\n  PEP.register('header', {\n    init: function (root, ctx) {\n      var cfg = ctx.config || {}, flags = cfg.flags || {}, cleared = flags.COUNSEL_CLEARED || {};\n      var q = function (s, el) { return (el || root).querySelector(s); };\n      var qa = function (s, el) { return Array.prototype.slice.call((el || root).querySelectorAll(s)); };\n      var mq = function (s) { return window.matchMedia ? window.matchMedia(s) : { matches: false }; };\n\n      // ---- the P: the live 3D mark with its edge light (02-logo3d). If the 3D engine is off, the name stands alone.\n      var mark = q('.pep-header-mark');\n      function announce() { if (mark) { ctx.emit('logo3d:slot', { el: mark, kind: 'mark', phase: 2.1, hold: true, edge: true, interactive: true }); } }\n      ctx.on('logo3d:ready', announce);\n      announce();\n      ctx.on('logo3d:off', function () { root.setAttribute('data-3d', 'off'); });\n      // The bar is solid chrome now and always stands over the 3D canvas (so its panels cover the page's 3D). The engine\n      // lifts the P's own pixels onto its small edge canvas every frame; they are copied 1:1, frame by frame, onto a\n      // canvas inside the bar, so the live P (same pixels, same turn) is drawn in front of the chrome.\n      if (mark) {\n        var mirror = document.createElement('canvas'), mcx = mirror.getContext('2d'), edge = null;\n        mirror.className = 'pep-header-mirror'; mirror.setAttribute('aria-hidden', 'true');\n        mark.appendChild(mirror);\n        (function copy() {\n          edge = edge && edge.isConnected ? edge : document.querySelector('.pep-logo3d-edge');\n          if (edge && edge.width && edge.style.visibility === 'visible') {\n            if (mirror.width !== edge.width || mirror.height !== edge.height) { mirror.width = edge.width; mirror.height = edge.height; }\n            var er = edge.getBoundingClientRect(), mr = mark.getBoundingClientRect();\n            mirror.style.width = er.width + 'px'; mirror.style.height = er.height + 'px';\n            mirror.style.transform = 'translate(' + (er.left - mr.left).toFixed(2) + 'px,' + (er.top - mr.top).toFixed(2) + 'px)';\n            mcx.clearRect(0, 0, mirror.width, mirror.height); mcx.drawImage(edge, 0, 0);\n            mirror.style.visibility = 'visible';\n          } else if (mirror.style.visibility !== 'hidden') { mirror.style.visibility = 'hidden'; }\n          window.requestAnimationFrame(copy);\n        })();\n      }\n\n      // ---- counsel switch: product names show in a preview, or once counsel clears them\n      var namesOpen = !!(flags.PREVIEW || cleared.names);\n      qa('[data-gate=\"names\"]').forEach(function (el) { el.hidden = !namesOpen; });\n      qa('[data-gate-off=\"names\"]').forEach(function (el) { el.hidden = namesOpen; });\n      var shopTo = namesOpen ? '#lineup' : '#shelf';\n      qa('[data-to-shop]').forEach(function (a) { a.setAttribute('href', shopTo); });\n\n      var narrow = mq('(max-width: 1199px)');\n      var menuKey = q('[data-menu-key]'), pep = q('[data-key=\"peptides\"]'), drop = q('[data-drop]'), row = q('.pep-header-row');\n      var dropLi = pep ? pep.closest('li') : null, keys = q('#pep-header-keys');\n      var dropOpen = function () { return root.hasAttribute('data-drop-open'); };\n      var menuOpen = function () { return root.hasAttribute('data-menu-open'); };\n\n      // ---- the bar steps out of the way, and back; away from the top it floats over the page\n      var tucked = false, lastY = window.pageYOffset || 0, tuckNext = false, floating = null;\n      function show() { if (tucked) { tucked = false; root.removeAttribute('data-tuck'); } }\n      function tuck() {\n        if (tucked || dropOpen() || menuOpen() || root.contains(document.activeElement)) { return; }\n        tucked = true; root.setAttribute('data-tuck', '');\n      }\n      function float(y) {\n        var f = y >= 140;\n        if (f === floating) { return; }\n        floating = f;\n        if (f) { root.setAttribute('data-float', ''); } else { root.removeAttribute('data-float'); }\n      }\n      float(lastY);\n      window.addEventListener('scroll', function () {\n        var y = window.pageYOffset || 0, dy = y - lastY;\n        lastY = y;\n        float(y);\n        if (y < 140) { tuckNext = false; show(); return; }\n        if (tuckNext) { tuckNext = false; tuck(); return; }\n        if (dy > 6) { tuck(); } else if (dy < -6) { show(); }\n      }, { passive: true });\n      // The keyboard reaching the tucked bar: the bar is off the top of the window, so the browser scrolls the page to\n      // centre the focused key (about half a window), although the bar is sticky and comes back by itself. The page is put\n      // back where the visitor was reading in the same step as the focus (before anything is drawn), and the bar comes\n      // back at once, with no slide (data-snap), so the focused key is on the screen from then on.\n      var tabY = null;\n      function back(y) { try { window.scrollTo({ top: y, behavior: 'instant' }); } catch (err) { window.scrollTo(0, y); } }\n      document.addEventListener('keydown', function (e) { if (e.key === 'Tab') { tabY = window.pageYOffset || 0; } }, true);\n      root.addEventListener('focusin', function () {\n        if (!tucked) { return; }\n        var y = tabY === null ? (window.pageYOffset || 0) : tabY;\n        root.setAttribute('data-snap', '');\n        show();\n        void root.offsetHeight;             // the bar is in its place now, not at the end of a slide\n        if (Math.abs((window.pageYOffset || 0) - y) > 2) { lastY = y; back(y); }\n        setTimeout(function () {             // and once more, should the browser scroll after the focus event\n          if (Math.abs((window.pageYOffset || 0) - y) > 2) { lastY = y; back(y); }\n          root.removeAttribute('data-snap');\n        }, 60);\n      });\n      // once the entrance is over the bar is marked up (kept for anything that listens for it)\n      var entrance = document.querySelector('[data-module=\"entrance\"]');\n      function up() { root.setAttribute('data-up', ''); }\n      if (!entrance || entrance.hidden) { up(); } else { ctx.on('entrance:done', up); setTimeout(up, 5600); }\n\n      // ---- the drop-down under PEPTIDES\n      function place() {                    // centred under PEPTIDES, kept inside the window (wide windows only)\n        if (!drop || !pep || !row || narrow.matches) { return; }\n        var rr = row.getBoundingClientRect(), br = pep.getBoundingClientRect(), w = drop.offsetWidth || 880;\n        var cx = br.left + br.width / 2, min = w / 2 + 12, max = window.innerWidth - w / 2 - 12;\n        root.style.setProperty('--pep-header-dx', (Math.max(min, Math.min(max, cx)) - rr.left).toFixed(1) + 'px');\n      }\n      function setDrop(open) {\n        if (!pep) { return; }\n        if (open) { place(); root.setAttribute('data-drop-open', ''); show(); } else { root.removeAttribute('data-drop-open'); }\n        pep.setAttribute('aria-expanded', open ? 'true' : 'false');\n      }\n      function setMenu(open) {\n        if (!menuKey) { return; }\n        if (open) { root.setAttribute('data-menu-open', ''); show(); } else { root.removeAttribute('data-menu-open'); setDrop(false); }\n        menuKey.setAttribute('aria-expanded', open ? 'true' : 'false');\n      }\n      function closeAll() { setDrop(false); setMenu(false); }\n      window.addEventListener('resize', function () { if (dropOpen()) { place(); } });\n      if (narrow.addEventListener) { narrow.addEventListener('change', closeAll); } else if (narrow.addListener) { narrow.addListener(closeAll); }\n\n      var hovAt = 0, leaveT = 0;\n      if (pep && dropLi && drop) {\n        // hover opens it only on a real move of the mouse: when the page moves or opens under a resting pointer, the\n        // browser sends a move with no movement, and that must not open it again after Esc\n        dropLi.addEventListener('pointerenter', function (e) { if (e.pointerType === 'mouse' && !narrow.matches) { clearTimeout(leaveT); } });\n        dropLi.addEventListener('pointermove', function (e) {\n          if (e.pointerType !== 'mouse' || narrow.matches || dropOpen() || !(e.movementX || e.movementY)) { return; }\n          clearTimeout(leaveT); hovAt = Date.now(); setDrop(true);\n        });\n        dropLi.addEventListener('pointerleave', function (e) {\n          if (e.pointerType !== 'mouse' || narrow.matches) { return; }\n          leaveT = setTimeout(function () { setDrop(false); }, 220);\n        });\n        // a click just after the hover opened it keeps it open; otherwise a click (or Enter, or Space) toggles it\n        pep.addEventListener('click', function () { setDrop(Date.now() - hovAt < 500 ? true : !dropOpen()); hovAt = 0; });\n        // the keyboard leaving the key and its drop-down closes it\n        dropLi.addEventListener('focusout', function (e) { if (e.relatedTarget && !dropLi.contains(e.relatedTarget)) { setDrop(false); } });\n      }\n      if (menuKey && keys) {\n        menuKey.addEventListener('click', function () { setMenu(!menuOpen()); });\n        keys.addEventListener('focusout', function (e) { if (narrow.matches && e.relatedTarget && !keys.contains(e.relatedTarget) && e.relatedTarget !== menuKey) { setMenu(false); } });\n      }\n      document.addEventListener('keydown', function (e) {\n        if (e.key !== 'Escape' || e.defaultPrevented) { return; }\n        if (dropOpen()) { e.preventDefault(); setDrop(false); if (pep) { pep.focus(); } }\n        else if (menuOpen()) { e.preventDefault(); setMenu(false); if (menuKey) { menuKey.focus(); } }\n      });\n      document.addEventListener('pointerdown', function (e) {\n        if (!root.contains(e.target)) { closeAll(); return; }\n        if (dropOpen() && dropLi && !dropLi.contains(e.target) && !narrow.matches) { setDrop(false); }\n      });\n\n      // ---- the keys that take the visitor somewhere: the menu closes, and the bar steps away once the page has moved\n      function went(e) {\n        closeAll();\n        if (e && e.detail !== 0) {          // a mouse or a finger (the keyboard keeps its place in the menu)\n          if (document.activeElement && root.contains(document.activeElement)) { document.activeElement.blur(); }\n          tuckNext = true;\n        }\n      }\n      qa('[data-key=\"shop\"], [data-key=\"research\"], [data-key=\"about\"], [data-leave]').forEach(function (a) { a.addEventListener('click', went); });\n\n      // ---- cart: the key asks the cart to open; the count arrives from the cart over the bus\n      var cartKey = q('[data-cart-open]'), count = q('[data-cart-count]');\n      if (cartKey) { cartKey.addEventListener('click', function () { closeAll(); ctx.emit('cart:open', { from: cartKey }); }); }\n      ctx.on('cart:changed', function (c) { if (count && c) { count.textContent = String(c.count || 0); } });\n\n      // ---- the catalogue, names only, while names show\n      var cols = q('[data-cols]'), colTpl = q('[data-tpl=\"col\"]'), countEl = q('[data-count]'), failLine = q('[data-drop-fail]');\n      if (!namesOpen || !cols || !colTpl || !window.fetch) { return; }\n      cols.addEventListener('click', function (e) {\n        var a = e.target.closest ? e.target.closest('a[data-sku]') : null;\n        if (!a) { return; }\n        e.preventDefault();\n        var ask = { sku: a.getAttribute('data-sku'), focus: e.detail === 0, done: false };\n        went(e);\n        ctx.emit('lineup:go', ask);\n        if (!ask.done) { var to = document.querySelector(shopTo); if (to) { to.scrollIntoView(); } }      // the lineup could not stand on it: go to the lineup\n        ctx.track('menu_product', { sku: ask.sku });\n      });\n      var hidden = Array.isArray(cfg.hidden) ? cfg.hidden : [];    // config.js: products held back for counsel review\n      var flagged = Array.isArray(cfg.flagged) ? cfg.flagged.map(String) : [], flagTpl = q('[data-tpl=\"flag\"]');   // config.js: on show, tagged\n      fetch('assets/catalogue.json')\n        .then(function (r) { if (!r.ok) { throw new Error('catalogue ' + r.status); } return r.json(); })\n        .then(function (d) {\n          var list = (d && Array.isArray(d.products) ? d.products : []).filter(function (p) {\n            // the same rule as THE LINEUP: a bracketed placeholder name is preview only; a held-back product never shows\n            return p && p.sku && p.name && (flags.PREVIEW || String(p.name).indexOf('[') < 0) && hidden.indexOf(String(p.sku)) < 0;\n          });\n          if (!list.length) { throw new Error('catalogue empty'); }\n          var by = function (a, b) { return String(a.name).localeCompare(String(b.name), 'en', { sensitivity: 'base' }); };\n          var fam = function (p) { return String(p.family || '').toUpperCase(); };\n          var peps = list.filter(function (p) { return fam(p) === 'PEPTIDE'; }).sort(by);\n          var blends = list.filter(function (p) { return fam(p) === 'BLEND'; }).sort(by);\n          var other = list.filter(function (p) { return fam(p) !== 'PEPTIDE' && fam(p) !== 'BLEND'; }).sort(by);\n          // four columns: the peptides in three even parts, then the blends with the other compounds under them (so the\n          // whole list, every product, stays on one screen)\n          var third = Math.ceil(peps.length / 3), first = function (p) { return String(p.name).charAt(0).toUpperCase(); };\n          var span = function (g) { return g.length ? ' ' + first(g[0]) + '–' + first(g[g.length - 1]) : ''; };\n          var pepHead = cols.getAttribute('data-head-peptide'), lastCol = null;\n          var groups = [\n            { head: pepHead + span(peps.slice(0, third)), items: peps.slice(0, third) },\n            { head: pepHead + span(peps.slice(third, 2 * third)), items: peps.slice(third, 2 * third) },\n            { head: pepHead + span(peps.slice(2 * third)), items: peps.slice(2 * third) },\n            { head: cols.getAttribute('data-head-blend'), items: blends },\n            { head: cols.getAttribute('data-head-other'), items: other, under: true }\n          ];\n          groups.forEach(function (g, i) {\n            if (!g.items.length) { return; }\n            var col = colTpl.content.firstElementChild.cloneNode(true), h = q('.pep-header-col-h', col), ul = q('ul', col);\n            h.textContent = g.head; h.id = 'pep-header-col-' + i; ul.setAttribute('aria-labelledby', h.id);\n            g.items.forEach(function (p) {\n              var li = document.createElement('li'), a = document.createElement('a');\n              a.className = 'pep-header-item'; a.href = shopTo; a.setAttribute('data-sku', String(p.sku)); a.textContent = String(p.name);\n              li.appendChild(a);\n              // a product still with counsel (config.js flagged) carries its tag beside its name, here as everywhere else\n              if (flagTpl && flagged.indexOf(String(p.sku)) >= 0) {\n                var tag = flagTpl.content.firstElementChild.cloneNode(true);\n                tag.id = 'pep-header-flag-' + String(p.sku).replace(/[^a-z0-9-]/gi, '');\n                a.setAttribute('aria-describedby', tag.id);\n                li.setAttribute('data-flagged', ''); li.appendChild(tag);\n              }\n              ul.appendChild(li);\n            });\n            if (g.under && lastCol) { lastCol.appendChild(col); } else { cols.appendChild(col); lastCol = col; }\n          });\n          if (countEl) { countEl.textContent = list.length + ' ' + countEl.getAttribute(list.length === 1 ? 'data-one' : 'data-many'); }\n        })\n        .then(null, function () { if (failLine) { failLine.hidden = false; } });\n    }\n  });\n})();",
"hero.html": "<!-- module:10-hero -->\n<!-- 10-hero: the first screen is ONE card that sells (owner, Nov 13 2026: \"where is my hook?\"; the card \"not selling anything\";\n     \"so much wasted space\"; \"no white GRAND OPENING\"; \"the same type of indent in the card\" as the header has under the P):\n     GRAND OPENING folded into the ask as chrome, standing in a glass tab cut like the header's tab under the P; JOIN THE\n     FOUNDER CIRCLE in the house 3D chrome; the founder line in chrome gold (the offer gate: in preview builds and, on the\n     live site, only once flags.COUNSEL_CLEARED.offer is true; otherwise the safe wording shows in the same place); the\n     logo's blue light running through the card like the light through the P; one email field, one button, the unticked\n     consent (hook H01). The vial stands beside it. Headings shine but never move. No health wording anywhere in this file. -->\n<section data-module=\"hero\" id=\"top\" aria-labelledby=\"pep-hero-title\">\n  <div class=\"pep-hero-row\">\n    <div class=\"pep-hero-card\" id=\"join\" data-slot=\"hero\">\n      <i class=\"pep-hero-floor\" aria-hidden=\"true\"></i>\n      <h1 class=\"pep-hero-kicker\" id=\"pep-hero-title\"><span class=\"pep-hero-sr\">PEPTICITY </span><span class=\"pep-hero-kicker-face\">GRAND OPENING</span></h1>\n      <form class=\"pep-hero-form\" method=\"post\" action=\"\" data-hook=\"H01\" data-ghl-form=\"team-join\" data-effect=\"frm-103\" novalidate>\n        <h2 class=\"pep-hero-ask pep-hero-3d\" data-text=\"JOIN THE FOUNDER CIRCLE\"><span class=\"pep-hero-3d-face\">JOIN THE FOUNDER CIRCLE</span></h2>\n\n        <p class=\"pep-hero-offer\" data-gate=\"offer\" hidden><strong class=\"pep-hero-offer-big\" data-offer-text></strong></p>\n        <!-- the safe line has its own restock pair: the new-lot wording shows only in a preview or once restock is cleared -->\n        <p class=\"pep-hero-offer\" data-gate-off=\"offer\"><strong class=\"pep-hero-offer-big\" data-gate=\"restock\" hidden>FIRST ACCESS TO EVERY NEW LOT, AND YOUR FOUNDER CARD.</strong><strong class=\"pep-hero-offer-big\" data-gate-off=\"restock\">YOUR FOUNDER CARD AND PEPTICITY NEWS.</strong></p>\n\n        <i class=\"pep-hero-light\" aria-hidden=\"true\"></i>\n\n        <div class=\"pep-hero-step\" data-step=\"email\">\n          <label class=\"pep-hero-label\" for=\"pep-hero-email\">EMAIL</label>\n          <div class=\"pep-hero-fieldrow\">\n            <input class=\"pep-hero-input\" id=\"pep-hero-email\" name=\"email\" type=\"email\" autocomplete=\"email\" inputmode=\"email\" spellcheck=\"false\" required aria-describedby=\"pep-hero-email-err\">\n            <button class=\"pep-hero-btn\" type=\"submit\" data-effect=\"txt-09\">\n              <span class=\"pep-hero-btn-label\" data-gate=\"offer\" hidden>CLAIM MY FOUNDER SPOT</span>\n              <span class=\"pep-hero-btn-label\" data-gate-off=\"offer\">GET MY FOUNDER CARD</span>\n              <span class=\"pep-hero-btn-ring\" aria-hidden=\"true\"></span>\n              <span class=\"pep-hero-btn-tick\" aria-hidden=\"true\"></span>\n            </button>\n          </div>\n          <p class=\"pep-hero-err\" id=\"pep-hero-email-err\" role=\"alert\" hidden>That email looks incomplete.</p>\n\n          <label class=\"pep-hero-consent\">\n            <span class=\"pep-hero-tick\"><input class=\"pep-hero-check\" type=\"checkbox\" name=\"consent_email\" data-consent aria-describedby=\"pep-hero-consent-err\"></span>\n            <span class=\"pep-hero-consent-text\" data-consent-text>Yes, PEPTICITY may email me my welcome and PEPTICITY news. I can unsubscribe any time.</span>\n          </label>\n          <p class=\"pep-hero-err\" id=\"pep-hero-consent-err\" role=\"alert\" hidden>Tick the box so we can email your welcome.</p>\n\n          <p class=\"pep-hero-err\" data-send-err role=\"alert\" hidden>That did not go through. Please try again.</p>\n\n          <p class=\"pep-hero-fine\">For adults. Your details never go to ad platforms.</p>\n        </div>\n\n        <div class=\"pep-hero-step\" data-step=\"name\" hidden>\n          <p class=\"pep-hero-done\" tabindex=\"-1\" data-step-head>YOU'RE IN.</p>\n          <p class=\"pep-hero-next\">Add your first name for your founder card.</p>\n          <label class=\"pep-hero-label\" for=\"pep-hero-first\">FIRST NAME</label>\n          <div class=\"pep-hero-fieldrow\">\n            <input class=\"pep-hero-input\" id=\"pep-hero-first\" name=\"first_name\" type=\"text\" autocomplete=\"given-name\" maxlength=\"40\">\n            <button class=\"pep-hero-btn\" type=\"button\" data-save-name><span class=\"pep-hero-btn-label\">ADD MY NAME</span></button>\n          </div>\n          <button class=\"pep-hero-skip\" type=\"button\" data-skip-name>SKIP MY NAME</button>\n        </div>\n\n        <div class=\"pep-hero-step\" data-step=\"done\" hidden>\n          <p class=\"pep-hero-done\" tabindex=\"-1\" data-step-head>WELCOME TO THE FOUNDER CIRCLE<span data-first-name></span>.</p>\n          <p class=\"pep-hero-offer\" data-gate=\"offer\" hidden><strong class=\"pep-hero-offer-big\">WE'LL EMAIL YOUR PLACE IN LINE FOR THE FOUNDER OFFER.</strong></p>\n          <p class=\"pep-hero-next\">You're on the list. <span data-gate=\"restock\" hidden>You will hear first when a new lot is posted.</span></p>\n        </div>\n\n        <p class=\"pep-hero-preview\" data-gate=\"preview\" data-preview-note hidden>Preview only: nothing was sent. The offer shows for review and goes live once cleared.</p>\n      </form>\n    </div>\n\n    <div class=\"pep-hero-bottle\" tabindex=\"0\" role=\"button\" aria-label=\"Raise the light under the PEPTICITY vial\"\n         data-bottle-alt=\"PEPTICITY vial in clear glass with the PEPTICITY P printed on it, the logo's blue light coming up through the bottle\"></div>\n    <span data-gate=\"names\" data-bottle-line-source hidden>BPC-157 · 10 MG</span>\n  </div>\n</section>",
"hero.css": "/* 10-hero. Every selector starts with [data-module=\"hero\"] or .pep-hero-\n   TOP-APPLY v2: the first screen is ONE card that sells (owner, Nov 13 2026). The card is sized to its content and sits right\n   under the bar, so the join field is on the first screen at every size. It is the store's smoked glass with a chrome rim,\n   cut with big angled corners, and it carries the same glass tab as the header's P (steep walls stepping out of the card's\n   upper-left cut, 12 px in), where GRAND OPENING stands in chrome. JOIN THE FOUNDER CIRCLE is the house 3D chrome with the\n   logo's blue light through its waist; the founder line is the one chrome-gold accent; the logo's light runs through the card\n   like the light through the P, overhanging both sides. Headings shine (a slow sheen) and never move; nothing is flat white. */\n[data-module=\"hero\"] {\n  --pep-hero-blue: 42, 120, 255;            /* the logo's light, #2a78ff */\n  --pep-hero-chrome: linear-gradient(180deg, #ffffff 0%, #e6e9ed 24%, #b9bec5 40%, #6b7077 46%, rgba(42, 120, 255, 1) 49%, #cfe6ff 51%, rgba(42, 120, 255, 1) 53%, #6b7077 57%, #b9bec5 66%, #e6e9ed 82%, #b9bec5 100%);\n  /* chrome gold from the owner's pale ramp; its two deeper stops are cut with platinum so every lit pixel stays inside the\n     brand-lock gold limits (LAB b* at most 20, a* at most 6): never yellow, never orange */\n  --pep-hero-gold: linear-gradient(180deg, var(--pep-gold-5) 0%, var(--pep-gold-4) 32%, color-mix(in srgb, var(--pep-gold-3) 65%, var(--pep-plat-3)) 48%, color-mix(in srgb, var(--pep-gold-2) 70%, var(--pep-plat-2)) 54%, color-mix(in srgb, var(--pep-gold-3) 65%, var(--pep-plat-3)) 61%, var(--pep-gold-4) 76%, var(--pep-gold-5) 100%);\n  --pep-hero-sheen: linear-gradient(105deg, rgba(255, 255, 255, 0) 40%, rgba(255, 255, 255, .85) 50%, rgba(255, 255, 255, 0) 60%);\n  position: relative;\n  z-index: 1;\n  display: block;\n  padding: 40px clamp(12px, 2.4vw, 40px) clamp(28px, 6vh, 72px);   /* the top clears the header's tab by 18 px */\n  overflow-x: clip;\n}\n/* a lamp of its own behind the glass, so the card has the logo's light to bend */\n[data-module=\"hero\"]::before {\n  content: \"\";\n  position: absolute;\n  left: 50%;\n  top: 0;\n  width: min(70vw, 1000px);\n  height: min(80svh, 640px);\n  pointer-events: none;\n  transform: translateX(-50%);\n  background: radial-gradient(closest-side, rgba(var(--pep-hero-blue), .26), rgba(var(--pep-hero-blue), .08) 58%, rgba(var(--pep-hero-blue), 0) 100%);\n}\n.pep-hero-sr { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }\n\n/* the card and the vial stand together, as one pair about the page's centre line */\n.pep-hero-row {\n  position: relative;\n  display: grid;\n  grid-template-columns: minmax(0, 56vw) auto;\n  justify-content: start;\n  align-items: start;\n  gap: clamp(28px, 4.4vw, 84px);\n}\n\n/* ---------- the card: glass with a chrome rim, big cuts, and the header's tab echoed at its upper left ---------- */\n.pep-hero-card {\n  --t: 32px;                                /* the tab's height */\n  --tw: 236px;                              /* the tab's top, wide enough for GRAND OPENING */\n  --a: 40px;                                /* the big cuts (upper left, lower right) */\n  --b: 14px;                                /* the small nicks (upper right, lower left) */\n  --k: .4;                                  /* the tab's walls: .4 px across per px down (about 68 degrees), as the header's */\n  --px: clamp(22px, 2.4vw, 36px);           /* side padding */\n  --over: 22px;                             /* how far the light runs out past each side */\n  --x1: calc(var(--a) - 12px);              /* where the tab leaves the upper-left cut: 12 px in, as the header's leaves its cut */\n  --x2: calc(var(--x1) + (var(--t) + 12px) * var(--k));\n  --x3: calc(var(--x2) + var(--tw));\n  --x4: calc(var(--x3) + var(--t) * var(--k));\n  position: relative;\n  justify-self: stretch;\n  width: 100%;\n  padding: calc(var(--t) + 22px) var(--px) 24px;\n}\n.pep-hero-card::before,\n.pep-hero-card::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  z-index: 0;\n  pointer-events: none;\n}\n.pep-hero-card::before {                    /* smoked glass, lit from the upper middle */\n  background:\n    radial-gradient(70% 46% at 50% 0%, rgba(var(--pep-hero-blue), .16), rgba(var(--pep-hero-blue), 0) 100%),\n    linear-gradient(160deg, rgba(255, 255, 255, .09), rgba(255, 255, 255, .02) 44%, rgba(255, 255, 255, .05)),\n    linear-gradient(180deg, rgba(20, 20, 22, .55), rgba(11, 11, 12, .7));\n  -webkit-backdrop-filter: blur(14px) saturate(150%);\n          backdrop-filter: blur(14px) saturate(150%);\n  clip-path: polygon(\n    0 calc(var(--t) + var(--a)), var(--x1) calc(var(--t) + 12px), var(--x2) 0, var(--x3) 0, var(--x4) var(--t),\n    calc(100% - var(--b)) var(--t), 100% calc(var(--t) + var(--b)), 100% calc(100% - var(--a)), calc(100% - var(--a)) 100%,\n    var(--b) 100%, 0 calc(100% - var(--b)));\n}\n@supports not ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))) {\n  .pep-hero-card::before { background: rgba(16, 17, 19, .92); }\n}\n.pep-hero-card::after {                     /* the chrome rim, 1.2 px, along every cut and both walls of the tab */\n  opacity: .9;\n  background: linear-gradient(135deg, #ffffff, #6b7077 30%, #2a2d31 52%, #e6e9ed 78%, #b9bec5);\n  clip-path: polygon(evenodd,\n    0 calc(var(--t) + var(--a)), var(--x1) calc(var(--t) + 12px), var(--x2) 0, var(--x3) 0, var(--x4) var(--t),\n    calc(100% - var(--b)) var(--t), 100% calc(var(--t) + var(--b)), 100% calc(100% - var(--a)), calc(100% - var(--a)) 100%,\n    var(--b) 100%, 0 calc(100% - var(--b)), 0 calc(var(--t) + var(--a)),\n    1.2px calc(var(--t) + var(--a) + .5px), 1.2px calc(100% - var(--b) - .5px), calc(var(--b) + .5px) calc(100% - 1.2px),\n    calc(100% - var(--a) - .5px) calc(100% - 1.2px), calc(100% - 1.2px) calc(100% - var(--a) - .5px),\n    calc(100% - 1.2px) calc(var(--t) + var(--b) + .5px), calc(100% - var(--b) - .5px) calc(var(--t) + 1.2px),\n    calc(var(--x4) - .81px) calc(var(--t) + 1.2px), calc(var(--x3) - .81px) 1.2px, calc(var(--x2) + .81px) 1.2px,\n    calc(var(--x1) + 1.02px) calc(var(--t) + 12.67px), 1.2px calc(var(--t) + var(--a) + .5px));\n}\n.pep-hero-form { position: relative; z-index: 1; }\n\n/* ---------- GRAND OPENING: chrome, in the tab ---------- */\n.pep-hero-kicker {\n  position: absolute;\n  z-index: 1;\n  top: 0;\n  left: calc(var(--x2) - 4px);\n  width: calc(var(--tw) + 8px);\n  height: var(--t);\n  display: grid;\n  place-items: center;\n  margin: 0;\n  padding: 0 0 0 .32em;\n  font: 700 15px/1 var(--pep-font-display);\n  letter-spacing: .32em;\n  white-space: nowrap;\n}\n.pep-hero-kicker-face,\n.pep-hero-label,\n.pep-hero-done,\n.pep-hero-skip {                            /* platinum chrome with the blue light through its waist, and a slow sheen */\n  background-image: var(--pep-hero-sheen), var(--pep-hero-chrome);\n  background-size: 300% 100%, 100% 100%;\n  background-position: 120% 0, 0 0;\n  background-repeat: no-repeat;\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n.pep-hero-kicker-face { display: block; filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .6)); animation: pep-hero-sheen 8s ease-in-out 1.2s infinite; }\n@keyframes pep-hero-sheen { 0% { background-position: 120% 0, 0 0; } 50%, 100% { background-position: -20% 0, 0 0; } }\n\n/* ---------- the ask: the house 3D chrome (stepped depth behind a chrome face), the blue light through its waist ---------- */\n.pep-hero-ask {\n  --pep-hero-3d-step: .02em;\n  position: relative;\n  isolation: isolate;\n  margin: 0 0 12px;\n  font-family: var(--pep-font-display);\n  font-weight: 400;\n  font-size: clamp(28px, 3.05vw, 46px);\n  line-height: 1.08;\n  letter-spacing: .06em;\n  text-wrap: balance;\n  color: var(--pep-plat-3);\n}\n.pep-hero-3d::before {\n  content: attr(data-text);\n  content: attr(data-text) / \"\";\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  pointer-events: none;\n  color: var(--pep-black-0);\n  -webkit-text-fill-color: currentColor;\n  text-shadow:\n    calc(var(--pep-hero-3d-step) * 1) calc(var(--pep-hero-3d-step) * 1.2) 0 var(--pep-plat-1),\n    calc(var(--pep-hero-3d-step) * 2) calc(var(--pep-hero-3d-step) * 2.4) 0 var(--pep-plat-2),\n    calc(var(--pep-hero-3d-step) * 3) calc(var(--pep-hero-3d-step) * 3.6) 0 color-mix(in srgb, var(--pep-plat-1) 55%, var(--pep-black-0)),\n    calc(var(--pep-hero-3d-step) * 4) calc(var(--pep-hero-3d-step) * 4.8) 0 color-mix(in srgb, var(--pep-black-0) 45%, black),\n    calc(var(--pep-hero-3d-step) * 5) calc(var(--pep-hero-3d-step) * 6) 0 color-mix(in srgb, var(--pep-plat-1) 78%, var(--pep-plat-2)),\n    calc(var(--pep-hero-3d-step) * 6) calc(var(--pep-hero-3d-step) * 7.2) 0 var(--pep-black-0),\n    .1em .15em .14em rgba(0, 0, 0, .85),\n    0 0 .45em rgba(var(--pep-hero-blue), .35);\n}\n.pep-hero-3d-face {\n  display: block;\n  background-image: var(--pep-hero-sheen), var(--pep-hero-chrome);\n  background-size: 300% 100%, 100% 1.08em;\n  background-position: 120% 0, 0 0;\n  background-repeat: no-repeat, repeat-y;\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n  animation: pep-hero-sheen 8s ease-in-out infinite;\n}\n\n/* ---------- the founder line: the one chrome-gold accent on the card ---------- */\n.pep-hero-offer { margin: 0; font: 400 clamp(17px, 1.62vw, 24px)/1.3 var(--pep-font-display); letter-spacing: .07em; text-transform: uppercase; text-wrap: balance; color: var(--pep-plat-3); }\n.pep-hero-offer-big {\n  display: block;\n  font-weight: 400;\n  background-image: var(--pep-hero-sheen), var(--pep-hero-gold);\n  background-size: 300% 100%, 100% 1.3em;\n  background-position: 120% 0, 0 0;\n  background-repeat: no-repeat, repeat-y;\n  -webkit-background-clip: text;\n          background-clip: text;\n  -webkit-text-fill-color: transparent;\n  filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .7)) drop-shadow(0 0 10px rgba(var(--pep-hero-blue), .22));\n  animation: pep-hero-sheen 8s ease-in-out 2.4s infinite;\n}\n\n/* ---------- the logo's light through the card: a blade with a hot core, tapering to a point at both ends, overhanging both\n   sides like the light through the P; one slow glint travels along it ---------- */\n.pep-hero-light {\n  position: relative;\n  display: block;\n  height: 18px;\n  margin: 12px 7% 8px;                      /* a lens that thins to nothing well before the card's edges */\n  pointer-events: none;\n}\n.pep-hero-light::before {                   /* the halo */\n  content: \"\";\n  position: absolute;\n  inset: 0 6%;\n  background: radial-gradient(50% 50% at 50% 50%, rgba(var(--pep-hero-blue), .38), rgba(var(--pep-hero-blue), .1) 60%, rgba(var(--pep-hero-blue), 0) 100%);\n}\n.pep-hero-light::after {                    /* the rod and its core */\n  content: \"\";\n  position: absolute;\n  left: 0;\n  right: 0;\n  top: 50%;\n  height: 4px;\n  margin-top: -2px;\n  clip-path: polygon(0 50%, 9% 0, 91% 0, 100% 50%, 91% 100%, 9% 100%);\n  background:\n    linear-gradient(90deg, rgba(255, 255, 255, 0), rgba(255, 255, 255, .95), rgba(255, 255, 255, 0)) -40% 0 / 22% 100% no-repeat,\n    linear-gradient(180deg, rgba(var(--pep-hero-blue), 0), rgba(var(--pep-hero-blue), .55) 30%, rgba(var(--pep-hero-blue), .55) 70%, rgba(var(--pep-hero-blue), 0)),\n    linear-gradient(90deg, rgba(var(--pep-hero-blue), 0) 0%, rgba(var(--pep-hero-blue), .95) 16%, #cfe6ff 50%, rgba(var(--pep-hero-blue), .95) 84%, rgba(var(--pep-hero-blue), 0) 100%);\n  animation: pep-hero-glint 7s ease-in-out 1s infinite;\n}\n@keyframes pep-hero-glint { 0% { background-position: -40% 0, 0 0, 0 0; } 45%, 100% { background-position: 140% 0, 0 0, 0 0; } }\n\n/* ---------- the field, the button, the consent ---------- */\n.pep-hero-label { display: inline-block; margin: 0 0 6px; font: 700 14px/1.2 var(--pep-font-display); letter-spacing: .3em; }\n.pep-hero-fieldrow { display: flex; flex-direction: column; gap: 10px; align-items: stretch; }\n.pep-hero-input {                           /* cut at two corners, the rim drawn along the cuts (a field has no pseudo layers) */\n  --k: 22px;\n  --rim: var(--pep-plat-2);\n  --rim-cut: var(--pep-plat-3);\n  flex: 1 1 auto;\n  min-width: 0;\n  height: 56px;\n  padding: 0 16px 0 22px;\n  font-size: 18px;\n  color: var(--pep-plat-4);\n  caret-color: var(--pep-light, #2a78ff);\n  border: 0;\n  border-radius: 0;\n  background:\n    linear-gradient(135deg, transparent calc(50% - .8px), var(--rim-cut) 50%, transparent calc(50% + .8px)) 0 0 / var(--k) var(--k) no-repeat,\n    linear-gradient(135deg, transparent calc(50% - .8px), var(--rim-cut) 50%, transparent calc(50% + .8px)) 100% 100% / var(--k) var(--k) no-repeat,\n    linear-gradient(var(--rim), var(--rim)) var(--k) 0 / calc(100% - var(--k)) 1px no-repeat,\n    linear-gradient(var(--rim), var(--rim)) 0 100% / calc(100% - var(--k)) 1px no-repeat,\n    linear-gradient(var(--rim), var(--rim)) 0 var(--k) / 1px calc(100% - var(--k)) no-repeat,\n    linear-gradient(var(--rim), var(--rim)) 100% 0 / 1px calc(100% - var(--k)) no-repeat,\n    rgba(255, 255, 255, .05);\n  clip-path: polygon(var(--k) 0, 100% 0, 100% calc(100% - var(--k)), calc(100% - var(--k)) 100%, 0 100%, 0 var(--k));\n  transition: background-color .3s ease;\n}\n.pep-hero-input:hover { --rim: var(--pep-plat-3); --rim-cut: var(--pep-plat-4); }\n.pep-hero-input:focus-visible { outline: 0; --rim: var(--pep-light, #2a78ff); --rim-cut: var(--pep-light, #2a78ff); background-color: rgba(255, 255, 255, .08); box-shadow: inset 0 -3px 0 var(--pep-light, #2a78ff); }\n.pep-hero-input[aria-invalid=\"true\"] { --rim: var(--pep-light, #2a78ff); --rim-cut: var(--pep-light, #2a78ff); }\n\n/* BTN-109 / TXT-09: a slashed chrome blade with the doors' arrow end, the logo's light along its foot; hover lifts it and\n   grows its words, and one sheen crosses it */\n.pep-hero-btn {\n  --s: clamp(20px, 1.7vw, 26px);\n  position: relative;\n  flex: 0 0 auto;\n  width: 100%;\n  height: 58px;\n  padding: 0 34px;\n  overflow: hidden;\n  cursor: pointer;\n  border: 0;\n  border-radius: 0;\n  font: 700 clamp(16px, 1.25vw, 19px)/1 var(--pep-font-display);\n  letter-spacing: .16em;\n  white-space: nowrap;\n  color: var(--pep-black-0);\n  background: linear-gradient(100deg, #b9bec5 0%, #ffffff 16%, #e6e9ed 30%, #6b7077 50%, #e6e9ed 66%, #ffffff 80%, #b9bec5 100%);\n  box-shadow: inset 0 -3px 0 rgba(var(--pep-hero-blue), .85), inset 0 -10px 14px -8px rgba(var(--pep-hero-blue), .5);\n  clip-path: polygon(var(--s) 0, 100% 0, calc(100% - var(--s)) 100%, 0 100%);   /* slashed, never pointed */\n  transform: translateY(0);\n  transition: transform .45s var(--pep-ease), filter .45s ease;\n}\n.pep-hero-btn::after {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: -70%;\n  width: 55%;\n  pointer-events: none;\n  background: linear-gradient(100deg, rgba(255, 255, 255, 0), rgba(255, 255, 255, .85), rgba(255, 255, 255, 0));\n  transform: translateX(0);\n  transition: transform 0s;\n}\n.pep-hero-btn:hover,\n.pep-hero-btn:focus-visible { transform: translateY(-3px); filter: brightness(1.08); }\n.pep-hero-btn:hover::after,\n.pep-hero-btn:focus-visible::after { transform: translateX(330%); transition: transform 1.4s ease-in-out; }\n.pep-hero-btn:active { transform: translateY(1px); filter: brightness(.96); }\n.pep-hero-btn:focus-visible { outline: 0; box-shadow: inset 0 -5px 0 var(--pep-light, #2a78ff), inset 0 -14px 16px -8px rgba(var(--pep-hero-blue), .7); }\n.pep-hero-btn-label { position: relative; z-index: 1; display: inline-block; transition: opacity .3s ease, transform .45s var(--pep-ease); }\n.pep-hero-btn:hover .pep-hero-btn-label,\n.pep-hero-btn:focus-visible .pep-hero-btn-label { transform: scale(1.06); }\n\n/* FRM-103: the button keeps its size; the label gives way to a ring, then a tick */\n.pep-hero-btn-ring,\n.pep-hero-btn-tick { position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; margin: -13px 0 0 -13px; opacity: 0; }\n.pep-hero-btn-ring { width: 20px; height: 20px; margin: -10px 0 0 -10px; border: 2px solid rgba(11, 11, 12, .25); border-top-color: var(--pep-black-0); border-right-color: var(--pep-black-0); border-radius: 0; }\n.pep-hero-btn-tick::before {\n  content: \"\";\n  position: absolute;\n  left: 4px;\n  top: 2px;\n  width: 9px;\n  height: 16px;\n  border-right: 3px solid var(--pep-black-0);\n  border-bottom: 3px solid var(--pep-black-0);\n  transform: rotate(45deg) scale(.4);\n  transition: transform .35s var(--pep-ease);\n}\n.pep-hero-sending .pep-hero-btn-label { opacity: 0; }\n.pep-hero-sending .pep-hero-btn-ring { opacity: 1; animation: pep-hero-turn .7s linear infinite; }\n.pep-hero-sent .pep-hero-btn-label { opacity: 0; }\n.pep-hero-sent .pep-hero-btn-tick { opacity: 1; }\n.pep-hero-sent .pep-hero-btn-tick::before { transform: rotate(45deg) scale(1); }\n@keyframes pep-hero-turn { to { transform: rotate(360deg); } }\n\n.pep-hero-err { margin: 8px 0 0; font-size: 15px; color: var(--pep-plat-4); }\n.pep-hero-consent { display: flex; gap: 12px; align-items: flex-start; min-height: 44px; margin: 14px 0 0; font-size: 15px; line-height: 1.45; color: var(--pep-plat-3); cursor: pointer; }\n/* the tick box: a chrome frame cut at two corners round a black well, ticked in black on platinum */\n.pep-hero-tick {\n  flex: 0 0 auto;\n  display: block;\n  width: 30px;\n  height: 30px;\n  margin-top: -3px;\n  padding: 1.5px;\n  background: linear-gradient(150deg, var(--pep-plat-4), var(--pep-plat-2) 45%, var(--pep-plat-1) 60%, var(--pep-plat-3));\n  clip-path: polygon(13px 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%, 0 13px);\n  transition: transform .4s var(--pep-ease);\n}\n.pep-hero-consent:hover .pep-hero-tick { transform: translateY(-2px) scale(1.08); }\n.pep-hero-check {\n  -webkit-appearance: none;\n  appearance: none;\n  display: block;\n  width: 100%;\n  height: 100%;\n  margin: 0;\n  border: 0;\n  border-radius: 0;\n  outline: 0;\n  cursor: pointer;\n  background: var(--pep-black-0) no-repeat 50% 50% / 20px 20px;\n  clip-path: polygon(12.4px 0, 100% 0, 100% calc(100% - 12.4px), calc(100% - 12.4px) 100%, 0 100%, 0 12.4px);\n  transition: background-color .25s ease;\n}\n.pep-hero-check:checked {\n  background-color: var(--pep-plat-4);\n  background-image: url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 20'><path d='M3.5 10.5 8 15 16.5 5' fill='none' stroke='%230b0b0c' stroke-width='3' stroke-linecap='square' stroke-linejoin='miter'/></svg>\");\n}\n.pep-hero-tick:has(.pep-hero-check:focus-visible) { background: var(--pep-light, #2a78ff); padding: 2.5px; }\n.pep-hero-tick:has(.pep-hero-check[aria-invalid=\"true\"]) { background: var(--pep-light, #2a78ff); padding: 2.5px; }\n.pep-hero-fine { margin: 10px 0 0; font-size: 14px; color: var(--pep-plat-3); }\n.pep-hero-preview { margin: 14px 0 0; padding-top: 12px; border-top: 1px solid var(--pep-plat-1); font: 400 14px/1.5 var(--pep-font-display); letter-spacing: .06em; text-transform: uppercase; color: var(--pep-plat-3); }\n\n/* ---------- after joining: the member's own lines ---------- */\n.pep-hero-done { display: inline-block; margin: 0 0 8px; font: 400 clamp(22px, 2.2vw, 32px)/1.15 var(--pep-font-display); letter-spacing: .1em; filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .6)); }\n.pep-hero-done:focus { outline: 0; }\n.pep-hero-joined > .pep-hero-ask,\n.pep-hero-joined > .pep-hero-offer { display: none; }\n.pep-hero-next { margin: 0 0 16px; font-size: clamp(16px, 1.25vw, 19px); color: var(--pep-plat-3); }\n.pep-hero-step { animation: pep-hero-step-in .6s var(--pep-ease) both; }\n@keyframes pep-hero-step-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }\n.pep-hero-skip {\n  display: inline-block;\n  margin-top: 12px;\n  min-height: 44px;\n  padding: 0 4px;\n  font: 700 14px/1 var(--pep-font-display);\n  letter-spacing: .26em;\n  border: 0;\n  border-bottom: 1px solid var(--pep-plat-2);\n  border-radius: 0;\n  cursor: pointer;\n  transform: translateY(0) scale(1);\n  transition: transform .45s var(--pep-ease), border-color .3s ease;\n}\n.pep-hero-skip:hover,\n.pep-hero-skip:focus-visible { transform: translateY(-2px) scale(1.06); border-color: var(--pep-plat-4); outline: 0; }\n.pep-hero-skip:focus-visible { box-shadow: inset 0 -3px 0 var(--pep-light, #2a78ff); }\n\n/* ---------- the vial (06-bottle mounts it here; it never tilts: its label must stay square) ---------- */\n.pep-hero-bottle {\n  justify-self: start;\n  height: min(56vh, 560px);\n  aspect-ratio: 560 / 1058;\n  margin-right: calc(min(56vh, 560px) * -.09);   /* the picture's spare air on the outer side, so the pair reads centred */\n  cursor: pointer;\n}\n.pep-hero-bottle:focus-visible { outline: 0; box-shadow: inset 0 -3px 0 var(--pep-light, #2a78ff); }\n\n/* short laptop screens: the card tightens so the whole ask stays on the first screen */\n@media (min-width: 900px) and (max-height: 800px) {\n  [data-module=\"hero\"] { padding-top: 40px; }\n  .pep-hero-card { padding-bottom: 20px; }\n  .pep-hero-ask { margin-bottom: 8px; font-size: clamp(28px, 5.2vh, 40px); }\n  .pep-hero-offer { font-size: clamp(17px, 2.7vh, 21px); }\n  .pep-hero-light { margin-top: 8px; margin-bottom: 4px; }\n  .pep-hero-input { height: 52px; }\n  .pep-hero-btn { height: 54px; }\n  .pep-hero-consent { margin-top: 10px; }\n  .pep-hero-fine { margin-top: 6px; }\n  .pep-hero-bottle { height: min(60vh, 520px); margin-right: calc(min(60vh, 520px) * -.09); }\n}\n/* narrow windows and phones: the card first, the vial under it */\n@media (max-width: 899px) {\n  [data-module=\"hero\"] { padding: 48px 12px 28px; }\n  .pep-hero-row { grid-template-columns: minmax(0, 1fr); justify-content: stretch; gap: 22px; }\n  .pep-hero-card { --px: 18px; --over: 10px; }\n  .pep-hero-bottle { justify-self: center; height: auto; width: min(78vw, 330px); margin: 0; }\n}\n@media (max-width: 599px) {\n  [data-module=\"hero\"] { padding-top: 16px; }\n  .pep-hero-card { --t: 28px; --tw: 196px; --a: 30px; --b: 12px; padding-bottom: 20px; padding-top: calc(var(--t) + 18px); }\n  .pep-hero-kicker { font-size: 13px; letter-spacing: .3em; }\n  .pep-hero-ask { font-size: 27px; }\n  .pep-hero-offer { font-size: 16px; }\n  .pep-hero-input { height: 54px; }\n  .pep-hero-btn { height: 56px; padding: 0 30px 0 26px; font-size: 16px; letter-spacing: .12em; }\n  .pep-hero-consent { font-size: 14.5px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .pep-hero-kicker-face, .pep-hero-3d-face, .pep-hero-offer-big, .pep-hero-light::after { animation: none; }\n  .pep-hero-step { animation: none; }\n  .pep-hero-btn:hover, .pep-hero-btn:focus-visible, .pep-hero-skip:hover, .pep-hero-skip:focus-visible { transform: none; }\n  .pep-hero-consent:hover .pep-hero-tick { transform: none; }\n}\n\n/* ===== ROUND 3 (Jeff, Nov 14 2026): the card stands at the far left of the page, wider, and SITS IN 3D (the glass-cards\n   skill): real depth (perspective, the lettering and the form a layer nearer than the glass), a floor shadow and a blue\n   under-glow below it. It is seated, not moving: nothing here follows the pointer, so the headings never move. The card's\n   own design is the owner's next pick; only its place, width and seat are set here. ===== */\n.pep-hero-row { perspective: 1800px; perspective-origin: 28% 40%; }\n.pep-hero-card { transform-style: preserve-3d; }\n.pep-hero-floor {                           /* under the card: the shadow it casts and the logo's light spilling from below */\n  position: absolute;\n  left: 3%;\n  right: 3%;\n  top: calc(100% - 8px);\n  height: 54px;\n  pointer-events: none;\n  background:\n    radial-gradient(50% 46% at 50% 22%, rgba(var(--pep-hero-blue), .5), rgba(var(--pep-hero-blue), 0) 100%),\n    radial-gradient(50% 60% at 50% 40%, rgba(0, 0, 0, .75), rgba(0, 0, 0, 0) 100%);\n  transform: translateZ(-40px);\n}\n@media (min-width: 900px) {\n  .pep-hero-card { transform: rotateY(3deg) rotateX(1.2deg); transform-origin: 0 50%; }\n  .pep-hero-kicker,\n  .pep-hero-form { transform: translateZ(26px); }\n  .pep-hero-fieldrow { flex-direction: row; }\n  .pep-hero-btn { flex: 0 0 auto; width: auto; padding: 0 40px; }\n}\n@media (max-width: 899px) {\n  .pep-hero-floor { left: 6%; right: 6%; height: 40px; }\n}"
}


def die(msg):
    sys.stderr.write('apply.py: FAILED: ' + msg + '\n')
    sys.exit(1)


def one(pattern, html, what, flags=0):
    found = list(re.finditer(pattern, html, flags))
    if len(found) != 1:
        die('%s: expected exactly 1 anchor, found %d (%s)' % (what, len(found), pattern))
    return found[0]


def swap_inner(html, src_attr, tag, new_inner):
    """replace everything between <tag data-pep-src="src_attr" ...> and the next </tag>"""
    m = one(r'<' + tag + r' data-pep-src="' + re.escape(src_attr) + r'"[^>]*>', html, src_attr)
    end = html.find('</' + tag + '>', m.end())
    if end < 0:
        die(src_attr + ': no closing </' + tag + '>')
    return html[:m.end()] + '\n' + new_inner + '\n' + html[end:]


def swap_markup(html, comment, open_tag, close_tag, new_markup, what):
    """replace from the module comment to the end of the module's own element"""
    c = one(re.escape(comment), html, what + ' module comment')
    o = one(re.escape(open_tag), html, what + ' element')
    if o.start() < c.start():
        die(what + ': the element stands before its module comment')
    end = html.find(close_tag, o.end())
    if end < 0:
        die(what + ': no closing ' + close_tag)
    return html[:c.start()] + new_markup + html[end + len(close_tag):]


def main():
    if len(sys.argv) != 3:
        die('usage: python3 -I apply.py IN.html OUT.html')
    with open(sys.argv[1], encoding='utf-8') as f:
        html = f.read()

    # 05-header
    html = swap_markup(html, '<!-- module:05-header -->', '<header data-module="header"', '</header>', P['header.html'], '05-header')
    html = swap_inner(html, 'modules/05-header/header.css', 'style', P['header.css'])
    html = swap_inner(html, 'modules/05-header/header.js', 'script', P['header.js'])
    logo = list(re.finditer(r'<script data-pep-src="modules/05-header/pep-logo\.js"[^>]*>', html))
    if len(logo) > 1:
        die('pep-logo.js: more than one block')
    if logo:
        end = html.find('</script>', logo[0].end())
        if end < 0:
            die('pep-logo.js: no closing </script>')
        end += len('</script>')
        if html[end:end + 1] == '\n':
            end += 1
        html = html[:logo[0].start()] + html[end:]
    elif SIG not in html:
        die('pep-logo.js: block not found and this file was never applied')

    # 10-hero
    html = swap_markup(html, '<!-- module:10-hero -->', '<section data-module="hero"', '</section>', P['hero.html'], '10-hero')
    html = swap_inner(html, 'modules/10-hero/hero.css', 'style', P['hero.css'])

    # config.js: the two founder-offer values only
    cm = one(r'<script data-pep-src="config\.js">', html, 'config.js')
    cend = html.find('</script>', cm.end())
    if cend < 0:
        die('config.js: no closing </script>')
    cfg = html[cm.end():cend]
    m = one(r"(?m)^(  offer: \{[^}]*?\n    text: )'[^'\n]*'", cfg, 'config.js offer.text')
    cfg = cfg[:m.start()] + m.group(1) + "'" + OFFER_TEXT + "'" + cfg[m.end():]
    m = one(r'(?m)^(  teamOffer: \{[^}]*?\n    percent: )\d+', cfg, 'config.js teamOffer.percent')
    cfg = cfg[:m.start()] + m.group(1) + TEAM_PERCENT + cfg[m.end():]
    html = html[:cm.end()] + cfg + html[cend:]

    if SIG not in html:
        die('signature missing after apply')
    with open(sys.argv[2], 'w', encoding='utf-8') as f:
        f.write(html)
    print('apply.py: TOP applied -> ' + sys.argv[2])


if __name__ == '__main__':
    main()
